using Microsoft.EntityFrameworkCore;
using System.Net;
using System.Net.Mail;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
namespace Society.Api;
public record PlatformMessageWrite(Guid TenantId,string Name,string MemberKind,string Channel,string Purpose,string Term,string Subject,string Body,Guid? ChapterId=null,Guid? AccountId=null,Guid? TemplateId=null,DateTimeOffset? ScheduledAt=null,int Revision=0);
public record PlatformTemplateMapping(string Body);
public record PlatformMessageSend(string PreviewToken);
public record PlatformMessageTest(string Address);
public record PlatformWhatsAppWrite(Guid TenantId,string Name,string Sender,string PhoneNumberId,string BusinessAccountId,string ApiVersion,string? Token,string? AppSecret,int PerMinute=20);
public record PlatformMessageRecipient(Guid MembershipId,Guid PersonId,Guid? UserId,string Name,string Number,string Destination,string Reason,Dictionary<string,string> Variables);
public static class PlatformCommunications {
 public const string Kind="PlatformBroadcast",EmailTemplate="platform-broadcast-html";
 static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);
 public static readonly string[] Variables=["member_name","membership_id","valid_till","society_name"];
 static string Hash(string value)=>CommunityService.Hash(value);
 static string First(params string?[] values)=>values.FirstOrDefault(v=>!string.IsNullOrWhiteSpace(v))?.Trim()??"";
 static string H(string value)=>WebUtility.HtmlEncode(value);
 static PlatformMessageWrite Settings(CommunicationCampaign c)=>JsonSerializer.Deserialize<PlatformMessageWrite>(c.Audience,Json)!;
 static string Render(string text,Dictionary<string,string> variables)=>Regex.Replace(text,@"\{\{\s*([^{}]+?)\s*\}\}",m=>variables.GetValueOrDefault(m.Groups[1].Value,""));
 static async Task<CommunicationCampaign> Campaign(AppDb db,Guid id)=>await db.Set<CommunicationCampaign>().SingleOrDefaultAsync(c=>c.Id==id&&c.Kind==Kind)??throw new AccessDeniedException();
 static async Task Validate(AppDb db,PlatformMessageWrite r){
  if(string.IsNullOrWhiteSpace(r.Name)||r.Subject==null||r.Body==null)throw new DomainException("Complete the campaign name, subject and message");
  if(r.Name.Trim().Length is <1 or >160||r.Subject.Length>180||r.Subject.Contains('\r')||r.Subject.Contains('\n')||r.Body.Length is <1 or >12000||r.MemberKind is not("Individual" or "Institutional")||r.Channel is not("Email" or "WhatsApp")||r.Purpose is not("MembershipNotice" or "OptionalCampaign")||r.Term is not("All" or "Current" or "Expired"))throw new DomainException("Complete the campaign name, audience, channel and message");
  if(r.Channel=="Email"&&string.IsNullOrWhiteSpace(r.Subject))throw new DomainException("Enter an email subject");
  if(r.Channel=="WhatsApp"&&r.Purpose!="OptionalCampaign")throw new DomainException("WhatsApp broadcasts require channel consent and an approved template");
  if(!await db.Tenants.AnyAsync(t=>t.Id==r.TenantId&&t.Status=="Active"))throw new DomainException("Choose an active society");
  if(r.ChapterId!=null&&!await db.Units.AnyAsync(u=>u.TenantId==r.TenantId&&u.Id==r.ChapterId))throw new DomainException("Choose a chapter in this society");
  if(r.ScheduledAt>DateTimeOffset.UtcNow.AddDays(365))throw new DomainException("Schedule within the next year");
  foreach(Match m in Regex.Matches(r.Body+" "+r.Subject,@"\{\{\s*([^{}]+?)\s*\}\}"))if(!Variables.Contains(m.Groups[1].Value))throw new DomainException("Unsupported personalization: "+m.Groups[1].Value);
  if(r.AccountId!=null&&!await db.Set<CommunicationAccount>().AnyAsync(a=>a.Id==r.AccountId&&a.TenantId==r.TenantId&&a.UnitId==null&&a.Channel==r.Channel))throw new DomainException("Choose a society-wide account matching the channel");
  if(r.Channel=="WhatsApp"){
   var t=await db.Set<CommunicationTemplate>().SingleOrDefaultAsync(t=>t.Id==r.TemplateId&&t.TenantId==r.TenantId&&t.Channel=="WhatsApp"&&t.ProviderAccountId==r.AccountId&&t.Active&&t.ProviderStatus=="APPROVED")??throw new DomainException("Choose a connected WhatsApp account and approved template");
   if(r.Body!=t.Body)throw new DomainException("WhatsApp content must match its approved template");MetaTemplates.Parameters(t,Variables.ToDictionary(v=>v,v=>v));
  }
 }
 static async Task<string?> Ready(AppDb db,IConfiguration config,IHostEnvironment env,PlatformMessageWrite r){
  if(r.AccountId==null)return r.Channel=="Email"&&(!string.IsNullOrEmpty(config["Smtp:Host"])||env.IsDevelopment())?null:"Connect and verify a sending account first";
  var a=await db.Set<CommunicationAccount>().SingleOrDefaultAsync(a=>a.Id==r.AccountId&&a.TenantId==r.TenantId&&a.UnitId==null&&a.Channel==r.Channel);
  return a?.Enabled==true&&a.Verified?null:"The selected sending account is disabled or unverified";
 }
 public static async Task<List<PlatformMessageRecipient>> Resolve(AppDb db,PlatformMessageWrite r,Guid? membershipId=null){
  var now=DateTimeOffset.UtcNow;var q=MembershipIdentity.Filter(db,db.Memberships.AsNoTracking().Where(m=>m.TenantId==r.TenantId&&m.Status=="Active"&&!m.PendingPayment&&!EF.Functions.JsonContains(m.Profile,"{\"adminArchived\":true}")),r.MemberKind);
  if(membershipId!=null)q=q.Where(m=>m.Id==membershipId);
  if(r.ChapterId!=null)q=q.Where(m=>m.ChapterId==r.ChapterId);
  if(r.Term=="Current")q=q.Where(m=>m.EffectiveFrom<=now&&(m.EndsAt==null||m.EndsAt>now));
  if(r.Term=="Expired")q=q.Where(m=>m.EndsAt!=null&&m.EndsAt<=now);
  var rows=await(from m in q join p in db.Persons on m.PersonId equals p.Id select new{m,p.FullName,p.UserId}).OrderByDescending(x=>x.UserId!=null).ThenBy(x=>x.m.Number).Take(10001).ToListAsync();if(rows.Count>10000)throw new DomainException("Narrow the audience to 10,000 memberships per campaign");
  var ids=rows.Where(x=>x.UserId!=null).Select(x=>x.UserId!.Value).Distinct().ToArray();var profileEmails=rows.Select(x=>{var profile=MembershipService.Json(x.m.Profile);return First(r.MemberKind=="Institutional"?profile["contactEmail"]?.ToString():null,profile["email"]?.ToString()).ToUpperInvariant();}).Where(x=>x!="").Distinct().ToArray();var contacts=await db.Users.Where(u=>ids.Contains(u.Id)||profileEmails.Contains(u.NormalizedEmail!)).ToListAsync();var users=contacts.ToDictionary(u=>u.Id,u=>u.Email??"");var contactIds=contacts.Where(u=>u.NormalizedEmail!=null).ToDictionary(u=>u.NormalizedEmail!,u=>(Guid?)u.Id);var contactUserIds=contacts.Select(u=>u.Id).ToArray();var prefs=await db.Set<CommunicationPreference>().Where(p=>p.TenantId==r.TenantId&&contactUserIds.Contains(p.UserId)).ToDictionaryAsync(p=>p.UserId);var emailOptouts=contacts.Where(u=>prefs.TryGetValue(u.Id,out var preference)&&!preference.Email).Select(u=>u.Email??"").ToHashSet(StringComparer.OrdinalIgnoreCase);var suppressed=await db.Set<CommunicationSuppression>().Where(s=>s.TenantId==r.TenantId&&s.Channel==r.Channel).Select(s=>s.DestinationHash).ToHashSetAsync();var society=await db.Tenants.Where(t=>t.Id==r.TenantId).Select(t=>t.Name).SingleAsync();var seenPeople=new HashSet<Guid>();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var result=new List<PlatformMessageRecipient>();
  foreach(var row in rows){var p=MembershipService.Json(row.m.Profile);var contactUser=row.UserId??contactIds.GetValueOrDefault(First(r.MemberKind=="Institutional"?p["contactEmail"]?.ToString():null,p["email"]?.ToString()).ToUpperInvariant());var pref=contactUser is Guid u?prefs.GetValueOrDefault(u):null;
   var destination=r.Channel=="Email"?(r.MemberKind=="Institutional"?First(p["contactEmail"]?.ToString(),p["email"]?.ToString(),row.UserId is Guid owner?users.GetValueOrDefault(owner):null):First(row.UserId is Guid id?users.GetValueOrDefault(id):null,p["email"]?.ToString())):r.MemberKind=="Institutional"?First(p["contactPhone"]?.ToString(),p["phone"]?.ToString()):First(p["phone"]?.ToString());
   if(r.Channel=="WhatsApp"){destination=Regex.Replace(destination,@"[\s()\-]","");if(Regex.IsMatch(destination,@"^[0-9]{10}$")&&new[]{"India","IN"}.Contains(p["country"]?.ToString(),StringComparer.OrdinalIgnoreCase))destination="+91"+destination;}
   var valid=r.Channel=="Email"?MailAddress.TryCreate(destination,out var address)&&address.Address.Equals(destination,StringComparison.OrdinalIgnoreCase):Regex.IsMatch(destination,@"^\+[1-9][0-9]{7,14}$");
   // Membership notices are administrative service messages. Optional outreach requires affirmative marketing consent.
   var optional=r.Purpose=="OptionalCampaign"||r.Channel=="WhatsApp";
   var optedOut=r.Channel=="Email"?emailOptouts.Contains(destination):pref!=null&&!pref.WhatsApp;
   var reason=!valid?"Missing or invalid contact":suppressed.Contains(Hash(destination.ToLowerInvariant()))?"Unsubscribed":optedOut?"Channel opted out":optional&&(!CommunityService.CommunicationAllowed(row.m.Privacy)||r.Channel=="WhatsApp"&&pref?.WhatsApp!=true)?"Consent required":(!seen.Add(destination)||!seenPeople.Add(row.m.PersonId))?"Duplicate address":"Eligible";
   var variables=new Dictionary<string,string>{{"member_name",row.FullName},{"membership_id",row.m.Number},{"valid_till",row.m.EndsAt==null?"Not specified":PlatformMemberAdmin.Date(row.m.EndsAt.Value.AddTicks(-1)).ToString("dd MMM yyyy")},{"society_name",society}};
   result.Add(new(row.m.Id,row.m.PersonId,contactUser,row.FullName,row.m.Number,destination,reason,variables));
  }return result;
 }
 static string Fingerprint(IEnumerable<PlatformMessageRecipient> rows)=>Hash(string.Join("\n",rows.Where(r=>r.Reason=="Eligible").OrderBy(r=>r.MembershipId).Select(r=>r.MembershipId+":"+r.Destination)));
 static object View(CommunicationCampaign c)=>new{c.Id,c.Name,c.Channel,c.Subject,c.Body,c.Status,c.Revision,c.ScheduledAt,c.CreatedAt,c.SnapshotCount,c.EnqueuedCount,c.AuthorId,settings=Settings(c)};
 static void Apply(CommunicationCampaign c,PlatformMessageWrite r){c.Name=r.Name.Trim();c.Channel=r.Channel;c.Subject=r.Subject.Trim();c.Body=r.Body;c.AccountId=r.AccountId;c.TemplateId=r.TemplateId;c.ScheduledAt=r.ScheduledAt??DateTimeOffset.UtcNow;c.Audience=JsonSerializer.Serialize(r,Json);}
 static string Html(CommunicationCampaign c,Dictionary<string,string> v,string? unsubscribe){var body=H(Render(c.Body,v)).Replace("\n","<br>");return "<!doctype html><html><body style='margin:0;background:#f4f1fa;font-family:Arial,sans-serif;color:#242037'><div style='max-width:640px;margin:24px auto;background:white;border:1px solid #e1daec;border-radius:14px;overflow:hidden'><div style='padding:28px;background:#27114b;color:white'><strong style='font-size:22px'>AIMER Society</strong><p>Membership communication</p></div><div style='padding:28px;line-height:1.75'><h1 style='font-size:22px'>"+H(Render(c.Subject,v))+"</h1>"+body+"<p>Warm regards,<br><strong>AIMER Society</strong></p></div><div style='padding:20px 28px;background:#faf8fe;font-size:12px;color:#625b70'>Membership ID: "+H(v.GetValueOrDefault("membership_id","Test preview"))+"<br>"+(unsubscribe==null?"Preview · no message has been sent":"<a href='"+H(unsubscribe)+"'>Manage email preferences / unsubscribe</a>")+"</div></div></body></html>";}
 public static void Map(RouteGroupBuilder api){
  var t=api.MapGroup("/platform/communications").RequireAuthorization().RequireRateLimiting("community");t.AddEndpointFilter(async(ctx,next)=>{var access=ctx.HttpContext.RequestServices.GetRequiredService<Access>();if(!await access.Platform())throw new AccessDeniedException();try{await access.RequirePlatform();}catch(AccessDeniedException){return Results.Problem(statusCode:403,title:"Confirm your administrator sign-in with MFA in My Account / Security to open the communication center");}return await next(ctx);});
  t.MapGet("/setup",async(AppDb db,IConfiguration config,IHostEnvironment env,Access a)=>new{testAddress=await db.Users.Where(u=>u.Id==a.UserId).Select(u=>u.Email).SingleAsync(),senderName="AIMER Society",senderAddress=config["Smtp:From"]??"Not configured",smtpReady=!string.IsNullOrWhiteSpace(config["Smtp:Host"])||env.IsDevelopment(),variables=Variables,societies=await db.Tenants.Where(t=>t.Status=="Active").OrderBy(t=>t.Name).Select(t=>new{t.Id,t.Name}).ToListAsync(),chapters=await db.Units.Where(u=>u.Status=="Active").Select(u=>new{u.Id,u.TenantId,u.Name}).ToListAsync(),accounts=await db.Set<CommunicationAccount>().Where(a=>a.UnitId==null).Select(a=>new{a.Id,a.TenantId,a.Name,a.Channel,a.Provider,a.Sender,a.Enabled,a.Verified,a.Health,a.PerMinute}).ToListAsync(),templates=await db.Set<CommunicationTemplate>().Where(t=>t.Active&&t.Channel=="WhatsApp").Select(t=>new{t.Id,t.TenantId,t.Name,t.Body,t.ProviderBody,t.Language,t.ProviderStatus,t.ProviderAccountId}).ToListAsync()});
  t.MapGet("/campaigns",async(AppDb db)=>await db.Set<CommunicationCampaign>().Where(c=>c.Kind==Kind).OrderByDescending(c=>c.CreatedAt).Take(200).Select(c=>new{c.Id,c.Name,c.Subject,c.Channel,c.Status,c.TenantId,c.AuthorId,c.ScheduledAt,c.CreatedAt,c.SnapshotCount,c.Revision,accepted=db.Outbox.Count(o=>o.CampaignId==c.Id&&(o.Status=="Accepted"||o.Status=="Delivered"||o.Status=="Read")),failed=db.Outbox.Count(o=>o.CampaignId==c.Id&&(o.Status=="Failed"||o.Status=="DeadLetter"||o.Status=="Unknown"||o.Status=="Unavailable"))}).ToListAsync());
  t.MapPost("/campaigns",async(PlatformMessageWrite r,AppDb db,Access a)=>{await Validate(db,r);var c=new CommunicationCampaign{TenantId=r.TenantId,AuthorId=a.UserId,Kind=Kind,Status="Draft"};Apply(c,r);db.Add(c);a.Audit(r.TenantId,"platform.communication.drafted",c.Id,new{r.MemberKind,r.Channel,r.Purpose});await db.SaveChangesAsync();return View(c);});
  t.MapPut("/campaigns/{id:guid}",async(Guid id,PlatformMessageWrite r,AppDb db,Access a)=>{await Validate(db,r);var c=await Campaign(db,id);if(c.Status!="Draft"||c.TenantId!=r.TenantId||c.Revision!=r.Revision)return Results.Conflict(new{message="Refresh this draft before editing"});Apply(c,r);c.Revision++;a.Audit(c.TenantId,"platform.communication.updated",c.Id);await db.SaveChangesAsync();return Results.Ok(View(c));});
  t.MapGet("/campaigns/{id:guid}",async(Guid id,AppDb db)=>{var c=await Campaign(db,id);var rows=await db.Set<CampaignRecipient>().Where(r=>r.CampaignId==id).OrderBy(r=>r.Id).Take(1000).Select(r=>new{r.Id,r.Destination,r.MembershipId,r.Status,delivery=r.OutboxId==null?null:db.Outbox.Where(o=>o.Id==r.OutboxId).Select(o=>new{o.Status,o.Attempts,o.Error,o.SentAt,o.DeliveredAt,o.ReadAt,o.ProviderId}).FirstOrDefault()}).ToListAsync();return new{campaign=View(c),recipients=rows};});
  t.MapGet("/campaigns/{id:guid}/preview",async(Guid id,AppDb db,Access a,IConfiguration config,IHostEnvironment env,IDataProtectionProvider protection)=>{var c=await Campaign(db,id);if(c.Status!="Draft")throw new DomainException("Only drafts can be previewed for sending");var r=Settings(c);await Validate(db,r);var rows=await Resolve(db,r);var vars=rows.FirstOrDefault(x=>x.Reason=="Eligible")?.Variables??new Dictionary<string,string>{{"member_name","Member"},{"membership_id","Preview"},{"valid_till","As recorded"},{"society_name","AIMER Society"}};var token=protection.CreateProtector("AIMER.PlatformBroadcast.Preview.v1").Protect(JsonSerializer.Serialize(new PreviewTicket(c.Id,c.Revision,a.UserId,Fingerprint(rows),DateTimeOffset.UtcNow.AddMinutes(15))));return new{total=rows.Count,eligible=rows.Count(x=>x.Reason=="Eligible"),skipped=rows.Where(x=>x.Reason!="Eligible").GroupBy(x=>x.Reason).Select(g=>new{reason=g.Key,count=g.Count()}),recipients=rows.Take(1000),html=c.Channel=="Email"?Html(c,vars,null):null,text=Render(c.Body,vars),subject=Render(c.Subject,vars),previewToken=token,sendBlocked=await Ready(db,config,env,r)};});
  t.MapPost("/campaigns/{id:guid}/send",async(Guid id,PlatformMessageSend request,AppDb db,Access a,IConfiguration config,IHostEnvironment env,IDataProtectionProvider protection)=>{
   await using var tx=await db.Database.BeginTransactionAsync();var locked=await db.Set<CommunicationCampaign>().FromSqlInterpolated($"SELECT * FROM \"CommunicationCampaign\" WHERE \"Id\"={id} FOR UPDATE").ToListAsync();var c=locked.SingleOrDefault(c=>c.Kind==Kind)??throw new AccessDeniedException();if(c.Status!="Draft")return Results.Ok(new{c.Id,c.Status,alreadyQueued=true});
   var r=Settings(c);await Validate(db,r);var blocked=await Ready(db,config,env,r);if(blocked!=null)throw new DomainException(blocked);PreviewTicket ticket;try{ticket=JsonSerializer.Deserialize<PreviewTicket>(protection.CreateProtector("AIMER.PlatformBroadcast.Preview.v1").Unprotect(request.PreviewToken))!;}catch{throw new DomainException("Preview the recipients again before sending");}
   var rows=await Resolve(db,r);if(ticket.Id!=id||ticket.User!=a.UserId||ticket.Revision!=c.Revision||ticket.Until<DateTimeOffset.UtcNow||ticket.Fingerprint!=Fingerprint(rows))throw new DomainException("The draft or recipient list changed. Preview it again");var eligible=rows.Where(x=>x.Reason=="Eligible").ToList();if(eligible.Count==0)throw new DomainException("No eligible recipients. Review the contact and consent report");
   c.SnapshotVersion++;foreach(var row in eligible)db.Add(new CampaignRecipient{TenantId=c.TenantId,CampaignId=id,SnapshotVersion=c.SnapshotVersion,MembershipId=row.MembershipId,PersonId=row.PersonId,UserId=row.UserId,Destination=row.Destination,Variables=JsonSerializer.Serialize(row.Variables)});c.SnapshotCount=eligible.Count;c.SnapshotAt=DateTimeOffset.UtcNow;c.Status="Scheduled";c.AuthorId=a.UserId;c.Revision++;a.Audit(c.TenantId,"platform.communication.queued",id,new{count=eligible.Count,r.MemberKind,r.Channel,r.Purpose,c.ScheduledAt});await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{c.Id,c.Status,count=c.SnapshotCount});
  });
  t.MapGet("/campaigns/{id:guid}/report.csv",async(Guid id,AppDb db,Access a)=>{var campaign=await Campaign(db,id);var rows=await db.Set<CampaignRecipient>().Where(r=>r.CampaignId==id).OrderBy(r=>r.Id).Select(r=>new{r.Destination,r.MembershipId,status=r.OutboxId==null?r.Status:db.Outbox.Where(o=>o.Id==r.OutboxId).Select(o=>o.Status).FirstOrDefault(),error=r.OutboxId==null?null:db.Outbox.Where(o=>o.Id==r.OutboxId).Select(o=>o.Error).FirstOrDefault()}).ToListAsync();string Cell(string? value){value??="";if(value.Length>0&&"=+-@\t\r".Contains(value[0]))value="'"+value;return "\""+value.Replace("\"","\"\"")+"\"";}var csv="Destination,Membership ID,Status,Detail\r\n"+string.Join("\r\n",rows.Select(r=>string.Join(",",new[]{Cell(r.Destination),Cell(r.MembershipId.ToString()),Cell(r.status),Cell(r.error)})));a.Audit(campaign.TenantId,"platform.communication.report.exported",id);await db.SaveChangesAsync();return Results.File(Encoding.UTF8.GetBytes("\uFEFF"+csv),"text/csv","Campaign-"+id+".csv");});
  t.MapPost("/campaigns/{id:guid}/cancel",async(Guid id,AppDb db,Access a)=>{await using var tx=await db.Database.BeginTransactionAsync();var c=await Campaign(db,id);c.Status="Cancelled";c.Revision++;await db.Outbox.Where(o=>o.CampaignId==id&&new[]{"Queued","Retry","Held"}.Contains(o.Status)&&o.LeaseUntil==null).ExecuteUpdateAsync(s=>s.SetProperty(o=>o.Status,"Cancelled"));a.Audit(c.TenantId,"platform.communication.cancelled",id);await db.SaveChangesAsync();await tx.CommitAsync();return Results.NoContent();});
  t.MapPost("/campaigns/{id:guid}/test",async(Guid id,PlatformMessageTest r,AppDb db,Access a,IConfiguration config,IHostEnvironment env)=>{var c=await Campaign(db,id);if(c.Channel!="Email"||c.Status!="Draft")throw new DomainException("Send a test from an email draft");var user=await db.Users.SingleAsync(u=>u.Id==a.UserId);if(!user.EmailConfirmed||!string.Equals(user.Email,r.Address,StringComparison.OrdinalIgnoreCase))throw new DomainException("Test messages can only go to your verified account email");if(await db.Audits.AnyAsync(x=>x.ActorId==a.UserId&&x.Action=="platform.communication.test"&&x.At>DateTimeOffset.UtcNow.AddMinutes(-1)))throw new DomainException("Wait one minute before another test");var ready=await Ready(db,config,env,Settings(c));if(ready!=null)throw new DomainException(ready);var rows=await Resolve(db,Settings(c));var v=rows.FirstOrDefault()?.Variables??Variables.ToDictionary(x=>x,x=>"Test preview");var token=CommunityService.Token();db.Add(new Outbox{TenantId=c.TenantId,SenderId=a.UserId,Channel="Email",Recipient=user.Email!,Subject="[TEST] "+Render(c.Subject,v),Body=Html(c,v,null),TemplateName=EmailTemplate,IdempotencyKey="platform-test:"+Guid.NewGuid(),AccountId=c.AccountId});a.Audit(c.TenantId,"platform.communication.test",id);await db.SaveChangesAsync();return Results.Ok(new{message="Test email queued to your verified account"});});
  MapAccounts(t);
 }
 record PreviewTicket(Guid Id,int Revision,Guid User,string Fingerprint,DateTimeOffset Until);
 static void MapAccounts(RouteGroupBuilder t){
  t.MapPost("/whatsapp",async(PlatformWhatsAppWrite r,AppDb db,Access a,CommunicationProviders providers)=>{
   if(!await db.Tenants.AnyAsync(x=>x.Id==r.TenantId&&x.Status=="Active")||r.Name.Length is <1 or >100||!Regex.IsMatch(r.PhoneNumberId,@"^\d{5,30}$")||!Regex.IsMatch(r.BusinessAccountId,@"^\d{5,30}$")||!Regex.IsMatch(r.ApiVersion,@"^v\d+\.\d+$")||r.Token?.Length is not(>10 and <10000)||r.AppSecret?.Length is not(>10 and <10000)||r.PerMinute is <1 or >120)throw new DomainException("Complete the WhatsApp Business account fields");
   var secret=new JsonObject{["token"]=r.Token,["wabaId"]=r.BusinessAccountId,["apiVersion"]=r.ApiVersion,["appSecret"]=r.AppSecret,["verifyToken"]=CommunityService.Token()};var account=new CommunicationAccount{TenantId=r.TenantId,Name=r.Name,Channel="WhatsApp",Provider="Meta",Sender=r.Sender,ProviderReference=r.PhoneNumberId,ProtectedSecrets=providers.Protect(secret.ToJsonString()),Enabled=true,PerMinute=r.PerMinute};db.Add(account);a.Audit(r.TenantId,"platform.communication.whatsapp.connected",account.Id);await db.SaveChangesAsync();return new{account.Id,account.Health,webhookUrl="/api/v1/communications/webhooks/"+account.Id,verifyToken=secret["verifyToken"]!.ToString()};
  });
  t.MapPost("/accounts/{id:guid}/verify",async(Guid id,AppDb db,Access a,CommunicationProviders providers,CancellationToken ct)=>{var account=await db.Set<CommunicationAccount>().SingleOrDefaultAsync(x=>x.Id==id&&x.UnitId==null)??throw new AccessDeniedException();account.Verified=await providers.Verify(account,providers.Secrets(account),ct);account.CheckedAt=DateTimeOffset.UtcNow;account.Health=account.Verified?"Sender verified":"Verification failed";a.Audit(account.TenantId,"platform.communication.account.verified",id,new{account.Verified});await db.SaveChangesAsync();return new{account.Verified,account.Health};});
  t.MapPost("/accounts/{id:guid}/sync",async(Guid id,AppDb db,Access a,CommunicationProviders providers,CancellationToken ct)=>{var account=await db.Set<CommunicationAccount>().SingleOrDefaultAsync(x=>x.Id==id&&x.UnitId==null&&x.Channel=="WhatsApp")??throw new AccessDeniedException();var count=await MetaTemplates.Sync(db,account,providers,ct);a.Audit(account.TenantId,"platform.communication.templates.synced",id,new{count});return new{count};});
  t.MapPut("/templates/{id:guid}/mapping",async(Guid id,PlatformTemplateMapping r,AppDb db,Access a)=>{var template=await db.Set<CommunicationTemplate>().SingleOrDefaultAsync(t=>t.Id==id&&t.Channel=="WhatsApp"&&t.UnitId==null)??throw new AccessDeniedException();if(r.Body==null||r.Body.Length>12000)throw new DomainException("Invalid template mapping");foreach(Match m in Regex.Matches(r.Body,@"\{\{\s*([^{}]+?)\s*\}\}"))if(!Variables.Contains(m.Groups[1].Value))throw new DomainException("Choose a supported member field");var mapped=new CommunicationTemplate{Body=r.Body,ProviderBody=template.ProviderBody};MetaTemplates.Parameters(mapped,Variables.ToDictionary(v=>v,v=>v));template.Body=r.Body;template.Revision++;a.Audit(template.TenantId,"platform.communication.template.mapped",id);await db.SaveChangesAsync();return Results.NoContent();});
  t.MapPost("/accounts/{id:guid}/disable",async(Guid id,AppDb db,Access a)=>{var account=await db.Set<CommunicationAccount>().SingleOrDefaultAsync(x=>x.Id==id&&x.UnitId==null)??throw new AccessDeniedException();account.Enabled=false;a.Audit(account.TenantId,"platform.communication.account.disabled",id);await db.SaveChangesAsync();return Results.NoContent();});
 }
 public static async Task Enqueue(AppDb db,IConfiguration config,CancellationToken ct){
  await using var tx=await db.Database.BeginTransactionAsync(ct);var now=DateTimeOffset.UtcNow;var locked=await db.Set<CommunicationCampaign>().FromSqlInterpolated($"SELECT * FROM \"CommunicationCampaign\" WHERE \"Kind\"={Kind} AND \"Status\" IN ('Scheduled','Dispatching') AND \"ScheduledAt\"<={now} ORDER BY \"ScheduledAt\" LIMIT 1 FOR UPDATE SKIP LOCKED").ToListAsync(ct);var c=locked.FirstOrDefault();if(c==null){await tx.CommitAsync(ct);return;}
  if(!await db.Users.AnyAsync(u=>u.Id==c.AuthorId&&u.PlatformAdmin,ct)||!await db.Tenants.AnyAsync(t=>t.Id==c.TenantId&&t.Status=="Active",ct)){c.Status="Cancelled";await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);return;}
  var rows=await db.Set<CampaignRecipient>().Where(r=>r.CampaignId==c.Id&&r.SnapshotVersion==c.SnapshotVersion&&r.Status=="Pending").OrderBy(r=>r.Id).Take(100).ToListAsync(ct);
  foreach(var row in rows){var v=JsonSerializer.Deserialize<Dictionary<string,string>>(row.Variables)!;var token=CommunityService.Token();var job=new Outbox{TenantId=c.TenantId,CampaignId=c.Id,SenderId=c.AuthorId,MembershipId=row.MembershipId,UserId=row.UserId,AccountId=c.AccountId,Channel=c.Channel,Recipient=row.Destination,Subject=Render(c.Subject,v),Body=c.Channel=="Email"?Html(c,v,(config["PublicUrl"]??"").TrimEnd('/')+"/unsubscribe?token="+token):Render(c.Body,v),UnsubscribeHash=Hash(token),IdempotencyKey="platform-campaign:"+c.Id+":"+row.PersonId,TemplateName=c.Channel=="Email"?EmailTemplate:null};
   if(c.Channel=="WhatsApp"){var template=await db.Set<CommunicationTemplate>().SingleAsync(t=>t.Id==c.TemplateId,ct);job.TemplateName=template.ProviderName;job.TemplateLanguage=template.Language;job.TemplateParameters=JsonSerializer.Serialize(MetaTemplates.Parameters(template,v));}db.Add(job);row.OutboxId=job.Id;row.Status="Queued";c.EnqueuedCount++;
  }c.Status=rows.Count<100?"Enqueued":"Dispatching";await db.SaveChangesAsync(ct);await tx.CommitAsync(ct);
 }
