   if(string.IsNullOrWhiteSpace(config["Smtp:Host"]))return new("Unavailable",Error:"Configure the society email service");using var smtp=new SmtpClient(config["Smtp:Host"],config.GetValue("Smtp:Port",587)){EnableSsl=true,Credentials=new NetworkCredential(config["Smtp:User"],config["Smtp:Password"]),Timeout=20000};var from=new MailAddress(config["Smtp:From"]!);using var mail=new MailMessage{From=new MailAddress(from.Address,"AIMER Society"),Subject=job.Subject,Body=job.Body,IsBodyHtml=true};mail.To.Add(job.Recipient);mail.ReplyToList.Add(from);await smtp.SendMailAsync(mail,ct);return new("Accepted","smtp:"+job.Id);
  }catch{return new("Unknown",Error:"Email outcome is uncertain; reconcile before resending");}
